def test_run_strict_vs_advisory_exit_codes(tmp_path: Path, capsys): src_file = tmp_path / 'sample.py'; src_file.write_text('VALUE = 10\n', encoding='utf-8'); manifest = tmp_path / 'mutations.json'; manifest.write_text(json.dumps({'mutations': [{'id': 'sample/inert', 'guard': 'inline', 'file': 'sample.py', 'find': 'VALUE = 10', 'replace': 'VALUE = 20', 'command': ['{python}', '-c', 'import sys; sys.exit(0)'], 'cwd': '.'}]}), encoding='utf-8'); rc_strict = mutation_check.run(advisory=False, manifest=manifest, repo_root=tmp_path, python=sys.executable); assert rc_strict == 1; rc_advisory = mutation_check.run(advisory=True, manifest=manifest, repo_root=tmp_path, python=sys.executable); assert rc_advisory == 0; captured = capsys.readouterr(); assert '::warning::guard is inert: sample/inert' in captured.out
def test_main_and_run_only_and_timeout_paths(tmp_path: Path, monkeypatch): src_file = tmp_path / 'sample.py'; original_code = 'VALUE = 10\n'; src_file.write_text(original_code, encoding='utf-8'); manifest = tmp_path / 'mutations.json'; manifest.write_text(json.dumps({'mutations': [{'id': 'sample/caught', 'guard': 'inline', 'file': 'sample.py', 'find': 'VALUE = 10', 'replace': 'VALUE = 20', 'command': ['{python}', '-c', 'import sys; sys.exit(1)'], 'cwd': '.'}]}), encoding='utf-8'); assert mutation_check.run(only='sample/caught', manifest=manifest, repo_root=tmp_path, python=sys.executable) == 0; assert mutation_check.run(only='no-such-id', manifest=manifest, repo_root=tmp_path, python=sys.executable) == 1; monkeypatch.setattr(mutation_check, 'REPO_ROOT', tmp_path); assert mutation_check.main(['--manifest', str(manifest), '--only', 'sample/caught']) == 0; slow_mut = mutation_check.Mutation(id='sample/slow', guard='inline', file='pkg/sample.py', find='VALUE = 10', replace='VALUE = 20', command=('{python}', '-c', 'import time; time.sleep(5)'), cwd='.'); (tmp_path / 'pkg').mkdir(exist_ok=True); pkg_file = tmp_path / 'pkg' / 'sample.py'; pkg_file.write_text(original_code, encoding='utf-8'); monkeypatch.setenv('PYTHONPATH', '/existing/pythonpath'); caught_t, why_t = mutation_check.apply_and_run(slow_mut, repo_root=tmp_path, python=sys.executable, timeout=0.1); assert caught_t is False; assert 'did not finish within 0.1s' in why_t; assert pkg_file.read_text(encoding='utf-8') == original_code
def test_run_total_timeout_marks_remaining_mutations_unproven(tmp_path: Path, capsys): src_file = tmp_path / 'sample.py'; src_file.write_text('VALUE = 10\n', encoding='utf-8'); manifest = tmp_path / 'mutations.json'; manifest.write_text(json.dumps({'mutations': [{'id': 'sample/after-deadline', 'guard': 'inline', 'file': 'sample.py', 'find': 'VALUE = 10', 'replace': 'VALUE = 20', 'command': ['{python}', '-c', 'import sys; sys.exit(1)'], 'cwd': '.'}]}), encoding='utf-8'); rc = mutation_check.run(manifest=manifest, repo_root=tmp_path, python=sys.executable, total_timeout=0.0); assert rc == 1; captured = capsys.readouterr(); assert 'unproven (total deadline exceeded)' in captured.out
